"""Render the general manipulation review from its independent research data."""
import html
import json

E = lambda value: html.escape(str(value), quote=True)

def build_manipulation(root, head, footer):
    records = json.loads((root / 'data/manipulation.json').read_text())
    groups = list(dict.fromkeys(p['group'] for p in records))
    slugs = {group: f'manip-group-{i+1}' for i, group in enumerate(groups)}
    def link(url, label):
        return f'<a href="{E(url)}" target="_blank" rel="noopener noreferrer">{E(label)}</a>'
    def card(p):
        video = link(p['video'], 'Author demos / video resources') if p['video'] else '<span class="muted">Separate video link not verified</span>'
        return f'''<details class="paper" id="{E(p['id'])}" data-year="{p['year']}"><summary><span class="paper-year">{p['year']}</span><span class="paper-main"><span class="paper-title">{E(p['title'])}</span><span class="tags"><span>{E(p['method'])}</span><span>{E(p['evidence'])}</span></span></span><span class="expand" aria-hidden="true">+</span></summary><div class="paper-body"><div class="provenance">{E(p['version'])} · {E(p['verification'])}</div><p class="mini-note">{E(p['authors'])}</p><p>{E(p['overview'])}</p><dl class="specs"><div><dt>Inputs / sensors</dt><dd>{E(p['inputs'])}</dd></div><div><dt>Action / architecture</dt><dd>{E(p['action'])}</dd></div><div><dt>Validation</dt><dd>{E(p['evidence'])}</dd></div><div><dt>Relevance / transfer</dt><dd>{E(p['relevance'])}</dd></div></dl><div class="findings"><section><h4>What is achieved</h4><p>{E(p['achievement'])}</p></section><section><h4>What remains unestablished</h4><p>{E(p['gap'])}</p><small>Review assessment of scope; not a universal novelty claim.</small></section></div><div class="resources">{link(p['url'],'Read paper')} {video}</div><p class="source-line">Evidence sources: {' · '.join(link(s['url'],s['label']) for s in p['sources'])}</p></div></details>'''
    nav = ''.join(f'<a href="#{slugs[g]}">{E(g)}<span>{sum(p["group"]==g for p in records):02}</span></a>' for g in groups)
    body = ''.join(f'<section class="paper-group" id="{slugs[g]}"><div class="section-head"><h2>{E(g)}</h2><span>{sum(p["group"]==g for p in records):02} papers</span></div>'+''.join(card(p) for p in records if p['group']==g)+'</section>' for g in groups)
    synthesis = (root / 'data/manipulation-synthesis.html').read_text()
    recent = sum(p['year'] >= 2025 for p in records)
    content = head.format(prefix='../', title='Robotic manipulation') + f'''<header class="top review-top"><a class="brand" href="../">VJ<span> / LITERATURE NOTEBOOK</span></a><a href="../">All projects</a></header><div class="review-layout"><aside><p class="eyebrow">Project 02</p><h2>Robotic<br>manipulation</h2><nav aria-label="Review sections"><a class="nav-major" href="#papers">Paper library<span>{len(records)}</span></a>{nav}<div class="nav-divider"></div><a href="#advances">Recent advances & gaps</a><a href="#workflow">Your woodworking workflow</a><a href="#gaps">Evidence & research gaps</a><a href="#methods">Methods compared</a><a href="#scope">Scope & sources</a></nav><p class="sidebar-note">Cameras + proprioception + wrist F/T.<br>Tactile-dependent papers are labeled.</p></aside><main id="main"><div class="review-heading"><p class="eyebrow">Robotics / Through 29 Sep 2026</p><h1>Vision, force<br><em>& action.</em></h1><p>A broad manipulation survey, with a dedicated path from wood-slab measurement to joining and drilling.</p><div class="review-meta"><span>{len(records)} papers</span><span>{recent} from 2025–2026 · earlier work & foundations</span><span>Research checked 29 Sep 2026</span></div></div><div class="brief"><strong>Two ways into the literature</strong><p>Explore generalist policies, dexterous hands, deformable objects, bimanual tasks and contact control—or follow the practical woodworking reading path.</p><a href="#advances">Start with recent advances</a><span class="brief-separator"> / </span><a href="#workflow">Woodworking workflow</a><span class="brief-separator"> / </span><a href="#gaps">Explore the gaps</a></div><section id="papers"><div class="library-head"><h2>Paper library</h2><p>Expand for sensors, methods, physical evidence and limits.</p></div><div class="library-tools" hidden><label>Search the review<input id="paper-search" type="search" placeholder="Try wooden pins, force, diffusion…" autocomplete="off"></label><label>Publication window<select id="paper-year"><option value="all">All years + foundations</option><option value="2026">2026 through 29 Sep</option><option value="2025">2025</option><option value="recent">2022–2024</option><option value="2024">2024</option><option value="2023">2023</option><option value="2022">2022</option><option value="older">Before 2022</option></select></label><label>Topic<select id="paper-topic"><option value="all">All topics</option>{"".join(f'<option value="{slugs[g]}">{E(g)}</option>' for g in groups)}</select></label><button id="clear-filters" type="button">Clear</button><p id="result-count" role="status" aria-live="polite"></p></div>{body}<p id="no-results" hidden>No matching papers. Try a broader term or clear the filters.</p></section>{synthesis}<section class="essay" id="scope"><p class="eyebrow">Review protocol</p><h2>Scope & sources</h2><p>This is a broad, curated narrative survey of robotic manipulation with a dedicated woodworking application path. The search cutoff is 29 September 2026, including 2025–2026 research and important earlier foundations. It is not an exhaustive bibliography of every manipulation paper; publication and indexing delays also limit same-day coverage.</p><p>Searches covered primary papers and author/publisher pages for visual policies, multimodal force learning, contact localization, shape reconstruction, timber assembly, compliant insertion, robotic drilling, dexterous hands, garment manipulation, mobile/bimanual systems, planning and benchmark reliability. Cards state the depth of verification. Abstract-level checks do not mean the full experimental protocol was audited. A missing video or missing woodworking result is not proof that none exists.</p><p>Preprints are included and labeled. Dates follow the cited version or publication record; CLASP is CoRL 2021 with 2022 proceedings. The timber collaboration paper appeared in January 2022 in a 2021 volume. Years usually follow first preprint or first online publication, with conference/journal and revision differences stated on cards. Recent September 2026 preprints are labeled and should be read as author-reported evidence, not established consensus. Historical 2024 versions remain useful baselines alongside newer papers.</p><p>Physical tests, simulation, datasets and theory are explicitly distinguished. Timber-specific evidence is separated from household, miniature-furniture, metal-machining and tactile-sensor examples. Gap statements and proposed experiments are review inferences. Author demonstrations are linked as resources, not as independently replicated reliability evidence.</p><p><a href="./papers.json" download>Download this project’s structured paper data</a></p></section>{footer}</main></div><script src="../app.js"></script><script src="./library.js"></script></body></html>'''
    target = root / 'dist/manipulation'
    target.mkdir(parents=True, exist_ok=True)
    (target / 'index.html').write_text(content)
    (target / 'papers.json').write_text(json.dumps(records, indent=2, ensure_ascii=False)+'\n')
    return len(records)
